export function animationCurveSampler(keys){const result=new Float64Array(1);return {evaluate(time){let low=0,high=keys.length;while(low<high){const mid=(low+high)>>>1;if(keys[mid].time<=time)low=mid+1;else high=mid;}const a=keys[Math.max(0,low-1)],b=keys[Math.min(keys.length-1,low)];result[0]=a===b||a.interpolation==='step'?a.value:a.value+(b.value-a.value)*Math.max(0,Math.min(1,(time-a.time)/(b.time-a.time)));return result;}};}
